export const tagNames={sea:'Море рядом',beach:'Настоящие пляжи',work:'Коворкинги и кафе',metro:'Удобное метро',malls:'Большие ТЦ',clubs:'Компьютерные клубы',mountains:'Горы и природа'};
export const defaultFilters={search:'',region:'',income:'',people:1,maxRent:'',housing:'',tags:[],matchMode:'all',durationAmount:'',durationUnit:'months',allowRenewal:false,routeType:'',visaFree:false,longStay:false,easyStay:false,verifiedOnly:false,bureaucracy:'',russian:false,english:false,climate:'',funding:'income',savings:'',months:7,reserve:false,citizenship:'',sort:'recommended',saved:false};
export function durationMonths(f){const n=Number(f.durationAmount);return Number.isFinite(n)&&n>0?n*(f.durationUnit==='years'?12:1):0}
export function evaluateRoute(route,months,allowRenewal=false){if(!months)return{fits:true,conditional:false,label:'Срок не ограничен фильтром'};const days=months*365.25/12;if(route.maxContinuousDays&&days>route.maxContinuousDays+1)return{fits:false,conditional:false,label:'Превышен непрерывный срок'};if(route.maxTotalMonths&&months>route.maxTotalMonths)return{fits:false,conditional:false,label:'Превышен предел программы'};const initial=route.durationMonths;if(initial!==null&&initial!==undefined&&months<=Number(initial))return{fits:true,conditional:false,label:'Подходит по сроку'};if(!allowRenewal)return{fits:false,conditional:false,label:'Нужно продление'};const extended=route.maxWithExtensionsMonths;if(extended&&months<=extended)return{fits:true,conditional:true,label:'С продлением'};if(route.allowRepeatedRenewal&&route.renewable&&initial)return{fits:true,conditional:true,label:'Потребуются повторные продления'};return{fits:false,conditional:false,label:'Срок не подтверждён'};}
export function monthly(city,people=1,housing='',reserve=false){const rent=Math.round(city.rent*(housing==='house'?1.8:housing==='condo'?1.15:1)*(1+Math.max(0,people-2)*.2));const daily=Math.round(city.living*(1+Math.max(0,people-1)*.7));const extra=reserve?Math.round((rent+daily)*.2):0;return{rent,daily,total:rent+daily+extra,reserve:extra}}
const asian=['ЮВА','Восточная Азия','Южная Азия','Центральная Азия','Ближний Восток','Кавказ'];
export function findMatches(countries,f,rates,saved=[]){const rate=rates[f.currency]||1;let query=f.search.trim().toLowerCase().replaceAll('ё','е');if(['куда угодно','весь мир','любая страна'].includes(query))query='';const requested=durationMonths(f);const hits=[];for(const c of countries){if(f.region&&!(f.region==='Азия'?asian.includes(c.region):c.region===f.region))continue;if(f.saved&&!saved.includes(c.id))continue;if(f.visaFree&&!c.visaFree||f.longStay&&c.longType==='unknown'||f.easyStay&&c.longType!=='free'||f.verifiedOnly&&!c.verified||f.russian&&!c.russian||f.english&&!c.english||f.climate&&c.climate!==f.climate||f.bureaucracy&&(!c.difficulty||c.difficulty>Number(f.bureaucracy))||f.citizenship&&(!c.citizenYears||c.citizenYears>Number(f.citizenship)))continue;
const routes=(c.routes||[]).filter(r=>(!f.routeType||f.routeType==='residence'&&['residence','nomad','work','study','family','passive'].includes(r.type)||r.type===f.routeType)&&evaluateRoute(r,requested,f.allowRenewal).fits);if((requested||f.routeType)&&!routes.length)continue;
const cities=c.cities.filter(city=>{if(query&&!`${c.name} ${c.region} ${city.name} ${city.wiki.replaceAll('_',' ')} ${c.region==='ЮВА'?'юго-восточная азия':''} ${asian.includes(c.region)?'азия':''}`.toLowerCase().replaceAll('ё','е').includes(query))return false;if(f.housing&&!city.housing.includes(f.housing))return false;const matches=f.tags.map(t=>city.tags.includes(t));if(matches.length&&(f.matchMode==='any'?!matches.some(Boolean):!matches.every(Boolean)))return false;const m=monthly(city,+f.people,f.housing,f.reserve);if(f.maxRent!==''&&m.rent>Number(f.maxRent)/rate)return false;if(f.funding==='income'&&f.income!==''&&m.total>Number(f.income)/rate)return false;if(f.funding==='savings'&&f.savings!==''&&m.total*(requested||Number(f.months))+m.rent*2>Number(f.savings)/rate)return false;return true});if(cities.length){const city=cities.reduce((a,b)=>monthly(a,+f.people,f.housing).total<=monthly(b,+f.people,f.housing).total?a:b);hits.push({country:c,cities,city,budget:monthly(city,+f.people,f.housing,f.reserve),routes,matchedTags:f.tags.filter(t=>city.tags.includes(t))})}}
if(f.sort==='budget')hits.sort((a,b)=>a.budget.total-b.budget.total);if(f.sort==='rent')hits.sort((a,b)=>a.budget.rent-b.budget.rent);if(f.sort==='name')hits.sort((a,b)=>a.country.name.localeCompare(b.country.name,'ru'));if(f.sort==='legal')hits.sort((a,b)=>(a.country.difficulty||9)-(b.country.difficulty||9));return hits;}
